using CondoManager.Application;
using CondoManager.Domain;
using Microsoft.EntityFrameworkCore;
namespace CondoManager.Infrastructure;
public sealed partial class AccountingService
{
    private async Task<ResidentReceipt> ResidentReceipt(Guid condo,Guid id,CancellationToken ct)=>await db.ResidentReceiptRows.SingleOrDefaultAsync(r=>r.Id==id && r.CondominiumId==condo,ct)??throw new NotFoundException();
    private async Task<ResidentReceiptDto> ReceiptResult(ResidentReceipt r,CancellationToken ct)
    {
        var link=await db.ReceiptBankLinks.SingleOrDefaultAsync(l=>l.ReceiptId==r.Id,ct);var rows=await db.ReceiptAllocations.Where(a=>a.ReceiptId==r.Id).OrderBy(a=>a.CreatedAt).ThenBy(a=>a.Id).ToListAsync(ct);
        var items=rows.Select(a=>new ReceiptAllocationDto(a.Id,a.InstallmentId,a.Amount,a.JournalEntryId,a.ReversesAllocationId,rows.Any(b=>b.ReversesAllocationId==a.Id))).ToArray();var allocated=rows.Sum(a=>a.ReversesAllocationId.HasValue?-a.Amount:a.Amount);
        return new(r.Id,r.AccountingPeriodId,r.FinancialAccountId,r.PaymentDate,r.Amount,r.Reference,r.DebtorId,r.PayerId,link?.Status.ToString()??"Unmatched",link?.JournalEntryId,allocated,r.Amount-allocated,items);
    }
    public async Task<IReadOnlyList<ResidentReceiptDto>> ResidentReceipts(Guid condo,Guid? period,CancellationToken ct)
    {await Condo(condo,ct);var result=new List<ResidentReceiptDto>();foreach(var r in await db.ResidentReceiptRows.Where(r=>r.CondominiumId==condo && (!period.HasValue || r.AccountingPeriodId==period)).OrderByDescending(r=>r.PaymentDate).ThenBy(r=>r.Id).ToListAsync(ct))result.Add(await ReceiptResult(r,ct));return result;}
    private async Task<JournalEntry> ValidateBank(ResidentReceipt receipt,Guid journalId,CancellationToken ct)
    {
        var journal=await db.JournalEntries.Include(j=>j.Lines).SingleOrDefaultAsync(j=>j.Id==journalId && j.CondominiumId==receipt.CondominiumId,ct)??throw new NotFoundException();
        var account=await db.FinancialAccounts.SingleAsync(f=>f.Id==receipt.FinancialAccountId && f.CondominiumId==receipt.CondominiumId,ct);
        if(journal.Kind!=JournalKind.Receipt || journal.AccountingPeriodId!=receipt.AccountingPeriodId || journal.Date!=receipt.PaymentDate || journal.Lines.Sum(l=>l.Debit)!=receipt.Amount || journal.Lines.Where(l=>l.AccountId==account.AccountId).Sum(l=>l.Debit-l.Credit)!=receipt.Amount || await db.JournalEntries.AnyAsync(j=>j.ReversesEntryId==journalId,ct))throw new ArgumentException("Movimento incompatibile: servono incasso generico non stornato, stessa data, esercizio, conto e importo esatto.");
        if(await db.ReceiptBankLinks.AnyAsync(l=>l.JournalEntryId==journalId && l.ReceiptId!=receipt.Id,ct))throw new InvalidOperationException("Movimento gia associato a un altro incasso.");return journal;
    }
    public Task<ResidentReceiptDto> RecordReceipt(Guid condo,ResidentReceiptInput input,CancellationToken ct)=>Write(condo,async()=>{
        Guard.Id(input.RequestId);var hash=FHash(input);var retry=await db.ResidentReceiptRows.SingleOrDefaultAsync(r=>r.CondominiumId==condo && r.RequestId==input.RequestId,ct);if(retry!=null){if(retry.RequestHash!=hash)throw new InvalidOperationException("Chiave incasso riutilizzata con dati diversi.");return await ReceiptResult(retry,ct);}
        if(input.RecordOnly && input.ExistingJournalId.HasValue)throw new ArgumentException("Scegliere incasso da riconciliare oppure movimento esistente.");
        var period=await Period(condo,input.AccountingPeriodId,input.PaymentDate,ct);var financial=await Financial(condo,input.FinancialAccountId,ct);
        if(input.PayerId.HasValue && !await db.People.AnyAsync(p=>p.Id==input.PayerId,ct))throw new NotFoundException();
        if(input.DebtorId.HasValue && (!await db.People.AnyAsync(p=>p.Id==input.DebtorId,ct) || !await db.InstallmentDebtors.AnyAsync(d=>d.CondominiumId==condo && d.PersonId==input.DebtorId,ct) && !await db.OwnershipPeriods.AnyAsync(a=>a.PersonId==input.DebtorId && db.PropertyUnits.Any(u=>u.Id==a.PropertyUnitId && u.CondominiumId==condo),ct)))throw new ArgumentException("Debitore non associato al condominio.");
        var receipt=new ResidentReceipt(TenantId,condo,period.Id,financial.Id,input.DebtorId,input.PayerId,input.PaymentDate,input.Amount,input.Reference,input.RequestId,hash);db.Add(receipt);
        if(input.ExistingJournalId.HasValue){var bank=await ValidateBank(receipt,input.ExistingJournalId.Value,ct);db.Add(new ReceiptBankLink(TenantId,condo,receipt.Id,bank.Id,true));}
        else if(!input.RecordOnly){var journal=new JournalEntry(TenantId,condo,period,input.PaymentDate,"Incasso condominiale",input.Reference,input.RequestId,hash,JournalKind.Receipt);journal.AddLine(await LedgerAccount(condo,financial.AccountId,ct),input.Amount,0);journal.AddLine(await Control(condo,AccountPurpose.UnallocatedReceipts,ct),0,input.Amount);db.Add(new ReceiptBankLink(TenantId,condo,receipt.Id,journal.Id,true));await Persist(journal,ct);}
        Audit("Resident.ReceiptRecorded",receipt.Id);await db.SaveChangesAsync(ct);return await ReceiptResult(receipt,ct);
    },ct);
    public Task<ResidentReceiptDto> MatchReceipt(Guid condo,Guid id,BankMatchInput input,bool confirm,CancellationToken ct)=>Write(condo,async()=>{
        var r=await ResidentReceipt(condo,id,ct);await Period(condo,r.AccountingPeriodId,r.PaymentDate,ct);await ValidateBank(r,input.JournalEntryId,ct);
        var link=await db.ReceiptBankLinks.SingleOrDefaultAsync(l=>l.ReceiptId==id,ct);
        if(link!=null && link.JournalEntryId!=input.JournalEntryId)throw new InvalidOperationException("Incasso gia associato: una nuova associazione richiede rettifica esplicita.");
        if(link==null){link=new(TenantId,condo,id,input.JournalEntryId);db.Add(link);}if(confirm)link.Reconcile();Audit(confirm?"Resident.ReceiptReconciled":"Resident.ReceiptMatched",id);await db.SaveChangesAsync(ct);return await ReceiptResult(r,ct);
    },ct);
    public async Task<IReadOnlyList<JournalDto>> AvailableBankMovements(Guid condo,CancellationToken ct)
    {await Condo(condo,ct);var rows=await db.JournalEntries.Include(j=>j.Lines).Where(j=>j.CondominiumId==condo && j.Kind==JournalKind.Receipt && !db.JournalEntries.Any(r=>r.ReversesEntryId==j.Id) && !db.ReceiptBankLinks.Any(l=>l.JournalEntryId==j.Id)).OrderByDescending(j=>j.Date).ToListAsync(ct);var result=new List<JournalDto>();foreach(var row in rows)result.Add(await JournalDtoFor(row,ct));return result;}
    private Task<decimal> PaidInstallment(Guid id,CancellationToken ct)=>db.ReceiptAllocations.Where(a=>a.InstallmentId==id).SumAsync(a=>a.ReversesAllocationId.HasValue?-a.Amount:a.Amount,ct);
    public Task<ResidentReceiptDto> AllocateReceipt(Guid condo,Guid id,AllocateReceiptInput input,CancellationToken ct)=>Write(condo,async()=>{
        var receipt=await ResidentReceipt(condo,id,ct);var hash=FHash(new{Operation="AllocateReceipt",Receipt=id,Input=input});var retry=await Retry(condo,input.RequestId,hash,ct);if(retry!=null)return await ReceiptResult(receipt,ct);
        if(!await db.ReceiptBankLinks.AnyAsync(l=>l.ReceiptId==id && l.Status==ReceiptMatchStatus.Reconciled,ct))throw new InvalidOperationException("Riconciliare l'incasso prima dell'attribuzione.");
        if(input.Date<receipt.PaymentDate)throw new ArgumentException("Attribuzione precedente all'incasso.");var period=await Period(condo,input.AccountingPeriodId,input.Date,ct);
        if(input.Allocations==null || input.Allocations.Count is <1 or >1000 || input.Allocations.Select(a=>a.InstallmentId).Distinct().Count()!=input.Allocations.Count)throw new ArgumentException("Da 1 a 1000 attribuzioni univoche.");
        var total=Money.Positive(input.Allocations.Sum(a=>Money.Positive(a.Amount)));var detail=await ReceiptResult(receipt,ct);if(total>detail.Unallocated)throw new InvalidOperationException("Attribuzione superiore all'importo non attribuito dell'incasso.");
        await EnsureResidentControls(condo,ct);var journal=new JournalEntry(TenantId,condo,period,input.Date,"Attribuzione incasso",receipt.Reference,input.RequestId,hash,JournalKind.ReceiptAttribution);
        foreach(var a in input.Allocations){var installment=await db.Installments.SingleOrDefaultAsync(i=>i.Id==a.InstallmentId && i.CondominiumId==condo,ct)??throw new NotFoundException();var plan=await Plan(condo,installment.PlanId,ct);if(plan.Status!=InstallmentPlanStatus.Approved || plan.JournalEntryId==null)throw new InvalidOperationException("Credito non emesso.");if(await db.JournalEntries.AnyAsync(j=>j.Id==plan.JournalEntryId && j.Date>input.Date,ct))throw new ArgumentException("Attribuzione precedente all emissione del credito.");var debtor=await db.InstallmentDebtors.SingleAsync(d=>d.Id==installment.InstallmentDebtorId,ct);if(receipt.DebtorId.HasValue && receipt.DebtorId!=debtor.PersonId)throw new ArgumentException("Rata di un debitore diverso da quello identificato nell'incasso.");if(a.Amount>installment.Amount-await PaidInstallment(installment.Id,ct))throw new InvalidOperationException("Attribuzione superiore al residuo della rata.");db.Add(new ReceiptAllocation(TenantId,condo,id,installment.Id,journal.Id,a.Amount));}
        journal.AddLine(await Control(condo,AccountPurpose.UnallocatedReceipts,ct),total,0);journal.AddLine(await Control(condo,AccountPurpose.ResidentReceivables,ct),0,total);await Persist(journal,ct);Audit("Resident.ReceiptAllocated",id);return await ReceiptResult(receipt,ct);
    },ct);
    public Task<ResidentReceiptDto> ReverseAllocation(Guid condo,Guid journalId,ReversalInput input,CancellationToken ct)=>Write(condo,async()=>{
        current.RequireAdmin();var hash=FHash(new{Operation="ReverseReceiptAllocation",Journal=journalId,Input=input});var original=await db.JournalEntries.Include(j=>j.Lines).SingleOrDefaultAsync(j=>j.Id==journalId && j.CondominiumId==condo && j.Kind==JournalKind.ReceiptAttribution,ct)??throw new NotFoundException();var rows=await db.ReceiptAllocations.Where(a=>a.JournalEntryId==original.Id && !a.ReversesAllocationId.HasValue).ToListAsync(ct);if(rows.Count==0 || rows.Select(a=>a.ReceiptId).Distinct().Count()!=1)throw new InvalidOperationException("Attribuzione non valida.");var receipt=await ResidentReceipt(condo,rows[0].ReceiptId,ct);var retry=await Retry(condo,input.RequestId,hash,ct);if(retry!=null)return await ReceiptResult(receipt,ct);
        if(await db.JournalEntries.AnyAsync(j=>j.ReversesEntryId==journalId,ct))throw new InvalidOperationException("Attribuzione gia rettificata.");if(input.Date<original.Date)throw new ArgumentException("Rettifica precedente all'attribuzione.");var period=await Period(condo,input.AccountingPeriodId,input.Date,ct);var journal=new JournalEntry(TenantId,condo,period,input.Date,Guard.Text(input.Reason),original.Reference,input.RequestId,hash,JournalKind.Reversal,null,original.Id);
        foreach(var line in original.Lines)journal.AddLine(await LedgerAccount(condo,line.AccountId,ct),line.Credit,line.Debit);db.AddRange(rows.Select(a=>new ReceiptAllocation(TenantId,condo,a.ReceiptId,a.InstallmentId,journal.Id,a.Amount,a.Id)));await Persist(journal,ct);Audit("Resident.AllocationReversed",receipt.Id);return await ReceiptResult(receipt,ct);
    },ct);
    public async Task<IReadOnlyList<CreditDto>> Credits(Guid condo,Guid? period,DateOnly? asOf,CancellationToken ct)
    {
        await Condo(condo,ct);var date=asOf??DateOnly.FromDateTime(DateTime.UtcNow);var rows=await (from i in db.Installments join p in db.InstallmentPlans on i.PlanId equals p.Id join d in db.InstallmentDebtors on i.InstallmentDebtorId equals d.Id join s in db.PlanSchedules on i.ScheduleId equals s.Id where i.CondominiumId==condo && p.JournalEntryId!=null && (!period.HasValue || p.AccountingPeriodId==period) orderby s.DueDate,d.UnitCode,d.PersonName select new{i,p,d,s}).ToListAsync(ct);
        var result=new List<CreditDto>();foreach(var row in rows){var paid=await PaidInstallment(row.i.Id,ct);var residual=row.i.Amount-paid;var status=row.i.Amount==0?"NotRequired":residual==0?"Paid":paid>0?"PartiallyPaid":row.s.DueDate<date?"Overdue":"Unpaid";result.Add(new(row.i.Id,row.p.Id,row.p.AccountingPeriodId,row.d.PropertyUnitId,row.d.UnitCode,row.d.PersonId,row.d.PersonName,row.s.DueDate,row.i.Amount,paid,residual,status,row.p.JournalEntryId));}return result;
    }
    public async Task<FinanceBalances> ResidentBalances(Guid condo,Guid? period,DateOnly? asOf,CancellationToken ct)
    {
        await Condo(condo,ct);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.RepeatableRead,ct);var date=asOf??DateOnly.FromDateTime(DateTime.UtcNow);var rows=await Credits(condo,period,date,ct);var receipts=await ResidentReceipts(condo,period,ct);var facts=await ResidentFacts(condo,ct);var selected=facts.Where(f=>!period.HasValue || f.OriginPeriodId==period.Value).ToArray();var positions=selected.GroupBy(f=>(f.PropertyUnitId,f.PersonId)).Select(g=>{var issued=g.Where(f=>f.Kind=="Issue").Sum(f=>f.Amount);var paid=-g.Where(f=>f.Kind=="Receipt").Sum(f=>f.Amount);var opening=g.Where(f=>f.Kind=="Opening").Sum(f=>f.Amount);var adjustment=g.Where(f=>f.Kind=="Settlement").Sum(f=>f.Amount);var nominal=rows.Where(r=>r.PropertyUnitId==g.Key.PropertyUnitId && r.DebtorId==g.Key.PersonId).ToArray();return new ResidentBalance(g.Key.PropertyUnitId,g.First().UnitCode,g.Key.PersonId,g.First().PersonName,issued,paid,g.Sum(f=>f.Amount),nominal.Where(r=>r.DueDate<date).Sum(r=>r.Residual),nominal.Where(r=>r.DueDate>=date).Sum(r=>r.Residual),opening,adjustment);}).ToArray();await tx.CommitAsync(ct);return new(date,positions,positions.Sum(p=>p.Issued),positions.Sum(p=>p.Allocated),positions.Sum(p=>p.Residual),receipts.Where(r=>r.Status=="Reconciled").Sum(r=>r.Unallocated),receipts.Where(r=>r.Status!="Reconciled").Sum(r=>r.Amount));
    }
}
